using System;using System.Windows;using System.Windows.Interop;using System.Runtime.InteropServices;
namespace Lumina {
    public static class DesktopWindowPolicy {
        [DllImport("user32.dll",EntryPoint="GetWindowLongW",SetLastError=true)]static extern int GetWindowLong(IntPtr window,int index);
        [DllImport("user32.dll",EntryPoint="SetWindowLongW",SetLastError=true)]static extern int SetWindowLong(IntPtr window,int index,int value);
        [DllImport("user32.dll",SetLastError=true)]static extern bool SetWindowPos(IntPtr window,IntPtr after,int x,int y,int width,int height,uint flags);
        public static int ToolStyle(int style){return (style|0x80)&~0x40000;}
        public static void Apply(Window window){try{var handle=new WindowInteropHelper(window).Handle;SetWindowLong(handle,-20,ToolStyle(GetWindowLong(handle,-20)));if(!SetWindowPos(handle,IntPtr.Zero,0,0,0,0,0x37))Store.Log(new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"刷新桌面窗口类型失败"));}catch(Exception ex){Store.Log(ex);}}
        public static Rect WorkArea(Window window,bool pointer=false,bool fullScreen=false){try{var handle=new WindowInteropHelper(window).Handle;System.Windows.Forms.Screen screen;if(pointer)screen=System.Windows.Forms.Screen.FromPoint(System.Windows.Forms.Cursor.Position);else if(handle!=IntPtr.Zero)screen=System.Windows.Forms.Screen.FromHandle(handle);else if(!double.IsNaN(window.Left)&&!double.IsNaN(window.Top)){var source=PresentationSource.FromVisual(window);var matrix=source!=null&&source.CompositionTarget!=null?source.CompositionTarget.TransformToDevice:System.Windows.Media.Matrix.Identity;var point=matrix.Transform(new Point(window.Left,window.Top));screen=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point((int)point.X,(int)point.Y));}else screen=System.Windows.Forms.Screen.PrimaryScreen;var bounds=fullScreen?screen.Bounds:screen.WorkingArea;var visual=PresentationSource.FromVisual(window);var from=visual!=null&&visual.CompositionTarget!=null?visual.CompositionTarget.TransformFromDevice:System.Windows.Media.Matrix.Identity;if(visual==null){using(var graphics=System.Drawing.Graphics.FromHwnd(IntPtr.Zero)){from=new System.Windows.Media.Matrix(96.0/graphics.DpiX,0,0,96.0/graphics.DpiY,0,0);}}var a=from.Transform(new Point(bounds.Left,bounds.Top));var b=from.Transform(new Point(bounds.Right,bounds.Bottom));return new Rect(a,b);}catch{return SystemParameters.WorkArea;}}
    }
}
